def expand(items, w):
    out = []
    for it in items:
        if it == 'W':
            out.extend(w)
        elif it[0] == 'R':
            out.extend(SP(it[1]))
        else:
            out.append((it[1], it[2]))
    return tuple(out)


def expand_cfg(cfg, w):
    st, pb, A, g0, s, items, G = cfg
    return (st, pb, A, g0, s, expand(items, w), G)


def waypoints_rle(j, b):
    """The full asserted waypoint chain TOP13 -> ... -> TOP14
    (plus the r14' = 2 / 4 / 6 and band closing waypoints), in
    run-length form: pair lists are item lists ('P', a, b) /
    ('R', n) / 'W'.  Kept unexpanded -- at this phase's scale
    one expanded chain is ~340 GB of tuples."""
    j14 = j - 58806193
    tail = (('P', 1, 1), ('R', b - 1))
    pts = []
    pts.append(('C', TOP13F, 34304475, 58806190, 2,
                (('P', 2 * j - 2, 2),) + tail, 1))
    pts.append(('B', TOP13F, 34304474, 1, 58806190,
                (('P', 2, 2), ('P', 2 * j - 2, 2)) + tail, 1))
    pts.append(('C', F14, 58806190, 1, 2,
                (('P', 2 * j - 4, 2),) + tail, 1))
    pts.append(('B', F14, 58806190, 1, 4,
                (('P', 2 * j - 4, 2),) + tail, 1))
    pts.append(('C', F14, 58806190, 3, 2,
                (('P', 2 * j - 6, 2),) + tail, 1))
    pts.append(('C', F14, 0, 3, 2, (('R', 58806190), 'W'), 1))
    pts.extend(CASCADE60_WPS)
    # TOP14 state reached; closing waypoints by r14' = 2 * j14.
    if j14 == 1:
        pts.append(('B', (74737819,) + TOP14F, 135985238, 1, 3,
                    (('R', b - 1),), 1))
    if j14 == 2:
        pts.append(('C', TOP14F, 74737818, 135985236, 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', TOP14F, 74737817, 1, 135985236,
                    (('P', 2, 2), ('P', 2, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', (135985237, 74737818) + TOP14F, 3, 1, 3,
                    (('R', b - 1),), 1))
    if j14 == 3:
        pts.append(('C', TOP14F, 74737818, 135985236, 2,
                    (('P', 4, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', TOP14F, 74737817, 1, 135985236,
                    (('P', 2, 2), ('P', 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('C', F15, 135985236, 1, 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', F15, 135985236, 1, 4,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('B', (135985237, 74737818) + TOP14F, 5, 1, 3,
                    (('R', b - 1),), 1))
    if j14 >= 4:
        pts.append(('C', TOP14F, 74737818, 135985236, 2,
                    (('P', 2 * j14 - 2, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', TOP14F, 74737817, 1, 135985236,
                    (('P', 2, 2), ('P', 2 * j14 - 2, 2),
                     ('P', 1, 1), ('R', b - 1)), 1))
        pts.append(('C', F15, 135985236, 1, 2,
                    (('P', 2 * j14 - 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', F15, 135985236, 1, 4,
                    (('P', 2 * j14 - 4, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('C', F15, 135985236, 3, 2,
                    (('P', 2 * j14 - 6, 2), ('P', 1, 1),
                     ('R', b - 1)), 1))
        pts.append(('B', F15, 135985236, 1, 2 * j14 - 2,
                    (('P', 2, 2), ('P', 1, 1), ('R', b - 1)), 1))
    return pts


def check_chain(j, b, cap=120000000):
    """check_chain with lazy waypoint expansion (the Phase 56
    scale forbids materialising the whole chain).  Matching,
    skip recording and lemmastep replay verification are
    hsim55's, verbatim in behaviour."""
    rle = waypoints_rle(j, b)
    w = W(2 * j - 117612386, b)
    N = len(rle)
    cache = {}

    def target(k):
        if k not in cache:
            if len(cache) > 24:
                cache.clear()
            cache[k] = norm(expand_cfg(rle[k], w))
        return cache[k]

    pos = -1
    status = fin = None
    used = set()
    src = TOP13(j, b)
    anchor = norm(src)
    skips = []  # (anchor, [skipped waypoints], landing)
    for rec in swalk(src, max_steps=cap):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            status, fin, used = rec[1], rec[2], rec[3]
            break
        if pos + 1 < N:
            if _matches(rec, target(pos + 1)):
                pos += 1
                anchor = target(pos)
            else:
                for k in range(pos + 2, min(pos + 9, N)):
                    if _matches(rec, target(k)):
                        skips.append((anchor,
                                      [target(t)
                                       for t in range(pos + 1, k)],
                                      target(k)))
                        pos = k
                        anchor = target(pos)
                        break
    assert pos == N - 1, \
        'j=%d b=%d: waypoint %d missing: %s' \
        % (j, b, pos + 1, fmt(target(pos + 1)))
    for (anchor, skipped, landing) in skips:
        targets = skipped + [landing]
        ti = 0
        cfg = anchor
        steps = 0
        while ti < len(targets) and steps < 200000:
            hit = lemmastep(cfg)
            assert hit is not None and hit[1] is not None, \
                ('verify replay unmatched', cfg)
            cfg = hit[1]
            steps += 1
            if norm(cfg) == targets[ti]:
                ti += 1
        assert ti == len(targets), \
            'j=%d b=%d: skipped waypoint not verified: %s' \
            % (j, b, fmt(targets[ti]))
    return status, fin, pos, used


def front_check(j, b):
    """The front segment TOP13(j, b) -> DIP14 spine (waypoints
    0..5), with check_chain's skip recording + lemmastep
    replay verification and early exit at the spine."""
    rle = waypoints_rle(j, b)
    w = W(2 * j - 117612386, b)
    pts = [norm(expand_cfg(c, w)) for c in rle[:6]]
    pos = -1
    anchor = norm(TOP13(j, b))
    skips = []
    for rec in swalk(TOP13(j, b), max_steps=20000000):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            break
        if pos + 1 < len(pts):
            if _matches(rec, pts[pos + 1]):
                pos += 1
                anchor = pts[pos]
            else:
                for k in range(pos + 2, min(pos + 9, len(pts))):
                    if _matches(rec, pts[k]):
                        skips.append((anchor, pts[pos + 1:k],
                                      pts[k]))
                        pos = k
                        anchor = pts[pos]
                        break
        if pos == len(pts) - 1:
            break
    assert pos == len(pts) - 1, \
        'front j=%d b=%d: waypoint %d missing' % (j, b, pos + 1)
    for (a0, skipped, landing) in skips:
        targets = skipped + [landing]
        ti = 0
        cfg = a0
        steps = 0
        while ti < len(targets) and steps < 200000:
            hit = lemmastep(cfg)
            assert hit is not None and hit[1] is not None, \
                ('front replay unmatched', cfg)
            cfg = hit[1]
            steps += 1
            if norm(cfg) == targets[ti]:
                ti += 1
        assert ti == len(targets), \
            'front j=%d b=%d: skipped waypoint not verified' \
            % (j, b)

def TOP14(j14, b):
    return ('B', TOP14F, 74737818, 1, 135985237,
            ((2 * j14, 2), (1, 1)) + tuple(SP(b - 1)), 1)


def main():
    """Execution structure (Phase 60 scale): NO span-sliced
    walk queues were built this phase (the Phase 56/57/58
    queues' remainders are still open; see
    build-logs-60/hsim60-parts-summary.txt).  Parts 2, 3, 4
    below are executed directly by phase60-work/finals60.py
    (walks from the TOP14 state, whose stack is just W).
    Part 1 (the canonical chain), Part 1b (the junk-tail
    probe) and Part 1c (front segments) are NOT executed
    this phase: the cascade segment is verified by the
    classifier chains (chain60_58806194_2/3.jsonl, labels
    and abstracted targets identical) and by the Rocq
    CASCADE60 lemma itself; the in-process front_check
    fails at the spine waypoint by design (the DIPGRIND
    descent yields ~117.6M walk records, over its 20M cap),
    exactly as in Phase 58/59.  Running this main()
    monolithically would re-execute Part 1 and 1b
    in-process (many hours at this scale)."""
    fails = 0
    used = set()
    # Part 1: the canonical full waypoint chain (58806194, 2).
    try:
        status, fin, pos, u = check_chain(58806194, 2)
        used.update(u)
        print('PASS chain j=58806194 b=2: %d waypoints in order, '
              'walk %s' % (len(waypoints_rle(58806194, 2)), status),
              flush=True)
    except AssertionError as e:
        fails += 1
        print('FAIL', e, flush=True)
    # Part 1b: CASCADE60 is tail-general -- junk tail probe.
    w0 = ((7, 2), (1, 1), (3, 2), (1, 2))
    src = ('C', F14, 0, 3, 2, tuple(SP(58806190)) + w0, 1)
    top14 = norm(('B', TOP14F, 74737818, 1, 135985237, w0, 1))
    ok = False
    for rec in swalk(src, max_steps=120000000):
        if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
            break
        if norm(rec) == top14:
            ok = True
            break
    print(('PASS' if ok else 'FAIL'),
          'tail-generality: TOP14 shape reached with junk tail',
          flush=True)
    fails += 0 if ok else 1
    # Part 1c: front segments at the other chain points (the
    # cascade parse is (j, beta)-uniform: classifier chains
    # at beta = 2, 3 are identical; the cascade segment is
    # walk-verified at the canonical point and for the junk
    # tail above).
    for (j, b) in [(58806194, 3), (58806195, 2), (58806196, 2),
                   (100000000, 2), (194791432, 2)]:
        try:
            front_check(j, b)
            print('PASS front segment j=%d b=%d: TOP13 -> DIP14 '
                  'spine' % (j, b), flush=True)
        except AssertionError as e:
            fails += 1
            print('FAIL', e, flush=True)
    # Part 2: TOP14-closing finals (walks from the TOP14
    # state, whose stack is just W).
    F15p = (74737819,) + TOP14F
    F16p = (135985237, 74737818) + TOP14F
    finals = {
        (1, 2): (F15p, 135985239),
        (1, 3): (F15p, 135985240),
        (2, 2): (F16p, 4),
        (2, 3): (F16p, 5),
        (3, 2): (F16p, 6),
        (3, 3): (F16p, 7),
        (1000000, 3): (F16p, 2000001),
        (135985239, 2): (F16p, 271970478),
    }
    for (j14, b), (fr, A) in sorted(finals.items()):
        status = fin = None
        for rec in swalk(TOP14(j14, b), max_steps=120000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                status, fin, u = rec[1], rec[2], rec[3]
                used.update(u)
                break
        want = ('B', tuple(fr), A, 1, 2 * b + 1, (), 1)
        ok = status == 'DONE' and norm(fin) == want
        print(('PASS' if ok else 'FAIL'),
              'TOP14 final j14=%d b=%d: %s (want A=%d frame %s)'
              % (j14, b, fmt(fin), A, list(fr)), flush=True)
        fails += 0 if ok else 1
    # Part 3: the fifteenth fence from the TOP14 state --
    # r14' >= 271970480 takes DIPGRIND at 135985236 (j14 is
    # TOP14's parameter).
    for (j14, b) in [(135985240, 2), (135985241, 2),
                     (200000000, 2)]:
        g15 = norm(('C', F15, 135985236, 3, 2,
                    ((2 * j14 - 6, 2), (1, 1)) + tuple(SP(b - 1)), 1))
        dip15 = norm(('C', F15, 0, 3, 2,
                      tuple(SP(135985236))
                      + ((2 * j14 - 271970478, 2), (1, 1))
                      + tuple(SP(b - 1)), 1))
        seen_g15 = seen_dip15 = False
        for rec in swalk(TOP14(j14, b), max_steps=120000000):
            if isinstance(rec, tuple) and rec and rec[0] == 'STATUS':
                break
            n = norm(rec)
            if n == g15:
                seen_g15 = True
            elif seen_g15 and n == dip15:
                seen_dip15 = True
                break
        ok = seen_g15 and seen_dip15
        print(('PASS' if ok else 'FAIL'),
              'fence j14=%d: GRIND15 then fifteenth DIPGRIND '
              'landing occur (r14p=%d)' % (j14, 2 * j14),
              flush=True)
        fails += 0 if ok else 1
    # Part 4: primitive-step audit over the terminating
    # walks (the classifier's step vocabulary is exactly
    # the PROVED_RULES lemma set).
    bad = used - PROVED_RULES
    print(('PASS' if not bad else 'FAIL'),
          'primitive rules used %s all in PROVED_RULES'
          % (sorted(used),), flush=True)
    fails += 0 if not bad else 1
    print()
    print('ALL PHASE 60 CHECKS PASS' if fails == 0
          else '%d FAILURES' % fails)
    return fails


if __name__ == '__main__':
    sys.exit(1 if main() else 0)
